import type { MedusaRequest, MedusaResponse } from "@medusajs/framework/http"
import { ContainerRegistrationKeys } from "@medusajs/framework/utils"
const actorId=(req:MedusaRequest)=>(req as any).auth_context?.actor_id||(req as any).auth_context?.auth_identity_id
async function sellerId(req:MedusaRequest,actor:string){try{const q=req.scope.resolve(ContainerRegistrationKeys.QUERY) as any;const {data}=await q.graph({entity:"seller_member",fields:["seller.id"],filters:{member_id:actor},pagination:{take:1}});return data?.[0]?.seller?.id||null}catch{return null}}
export async function GET(req:MedusaRequest,res:MedusaResponse){const spike=req.scope.resolve("spike") as any;const actor=actorId(req);if(!actor)return res.status(401).json({message:"Unauthorized"});const seller=await sellerId(req,actor);const revisions=seller?await spike.listSpikeProductRevisions({seller_id:seller},{take:500,order:{created_at:"DESC"}}):[];res.json({revisions})}
export async function POST(req:MedusaRequest,res:MedusaResponse){const spike=req.scope.resolve("spike") as any;const actor=actorId(req);if(!actor)return res.status(401).json({message:"Unauthorized"});const seller=await sellerId(req,actor);if(!seller)return res.status(403).json({message:"Seller account not found"});const b=(req.body||{}) as any;if(!b.product_id)return res.status(400).json({message:"product_id is required"});const revision=await spike.createSpikeProductRevisions({product_id:String(b.product_id),seller_id:seller,offer_id:b.offer_id?String(b.offer_id):null,status:"pending",changes:b.changes||{},rejection_reason:null});await spike.createSpikeNotifications({audience:"admin",seller_id:null,type:"product_revision",title:"تعديل منتج بانتظار الموافقة",body:String(b.changes?.title||b.product_title||b.product_id),entity_type:"product_revision",entity_id:revision.id,read:false});res.status(202).json({revision})}
